package com.core.docintel.pipeline.events;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.BiConsumer;
/** Small standalone execution service; contains no Studio control-plane or HTTP dependencies. */
public final class ApplicationServices implements AutoCloseable {
 @FunctionalInterface public interface Workflow {Object run(String input,RunEvents events) throws Exception;}
 @FunctionalInterface public interface Adapters {void wire(String mode,EventDispatcher dispatcher,PipelineDescriptor descriptor,WorkflowStateStore state);}
 private final Map<String,Workflow> workflows;private final Map<String,PipelineDescriptor> descriptors;private final Adapters adapters;private final Map<String,Session> runs=new LinkedHashMap<>();private final ExecutorService executor=Executors.newVirtualThreadPerTaskExecutor();private final Map<String,Object> template;
 private final Map<String,List<EventFilter>> views;
 private final Map<String,java.util.function.Supplier<EventAdapter>> eventDestinations=new LinkedHashMap<>();
 /** Optional host infrastructure observes future runs through the same bounded dispatcher. */
 public synchronized void addEventDestination(String id,java.util.function.Supplier<EventAdapter> factory){if(eventDestinations.putIfAbsent(Objects.requireNonNull(id),Objects.requireNonNull(factory))!=null)throw new IllegalArgumentException("Duplicate host event destination: "+id);}
 public ApplicationServices(Map<String,Workflow> workflows,Map<String,PipelineDescriptor> descriptors,Adapters adapters,Map<String,Object> template){this(workflows,descriptors,adapters,template,Map.of());}
 public ApplicationServices(Map<String,Workflow> workflows,Map<String,PipelineDescriptor> descriptors,Adapters adapters,Map<String,Object> template,Map<String,List<EventFilter>> views){this.workflows=Map.copyOf(workflows);this.descriptors=Map.copyOf(descriptors);this.adapters=adapters;this.template=Map.copyOf(template);this.views=Map.copyOf(views);}
 public Set<String> modes(){return workflows.keySet();}
 public Map<String,Object> application(){Map<String,Object> graphs=new LinkedHashMap<>();descriptors.forEach((mode,d)->graphs.put(mode,d.toMap()));return Map.of("modes",modes(),"descriptor",Map.of("name","Pipeline application","workflows",graphs),"template",template);}
 public synchronized Session create(String mode){if(!workflows.containsKey(mode))throw new IllegalArgumentException("Workflow is not available: "+mode);while(runs.size()>=100){String remove=runs.entrySet().stream().filter(e->e.getValue().finished).map(Map.Entry::getKey).findFirst().orElseThrow(()->new IllegalStateException("Run capacity reached."));runs.remove(remove);}String id=UUID.randomUUID().toString();PipelineDescriptor descriptor=descriptors.get(mode);WorkflowStateStore state=new WorkflowStateStore(id,descriptor,5000);EventDispatcher dispatcher=new EventDispatcher();adapters.wire(mode,dispatcher,descriptor,state);eventDestinations.forEach((destinationId,factory)->dispatcher.attachBlocking(destinationId,factory,List.of(EventFilter.all())));Session s=new Session(id,mode,state,dispatcher);runs.put(id,s);return s;}
 public Object execute(Session session,String input) throws Exception {if(!session.phase.compareAndSet(0,1))throw new CancellationException("Cancelled before starting.");session.events.event(null,null,"RUN_STARTED","Run started",Map.of(),null);long start=System.nanoTime();try{Object result=workflows.get(session.mode).run(input,session.events);if(!session.cancellationRequested&&"query".equals(session.mode))session.output=QueryOutput.of(result);session.events.event(null,null,session.cancellationRequested?"RUN_CANCELLED":"RUN_SUCCEEDED",session.cancellationRequested?"Stopped after cancellation":"Run completed",Map.of("outputSummary",DataSummaries.of(result)),elapsed(start));return result;}catch(InterruptedException|CancellationException e){session.events.event(null,null,"RUN_CANCELLED","Run cancelled",Map.of(),elapsed(start));throw e;}catch(Exception e){session.events.event(null,null,session.cancellationRequested?"RUN_CANCELLED":"RUN_FAILED",session.cancellationRequested?"Stopped after cancellation":Objects.toString(e.getMessage(),e.getClass().getSimpleName()),Map.of(),elapsed(start));throw e;}finally{session.events.closeReports();session.phase.set(2);session.finished=true;session.dispatcher.close();}}
 public String start(String mode,String input){Session s=create(mode);s.future=executor.submit(()->{try{execute(s,input);}catch(Exception ignored){}});return s.id;}
 public synchronized Session get(String id){Session s=runs.get(id);if(s==null)throw new NoSuchElementException("Run not found.");return s;}
 public synchronized List<Map<String,Object>> history(){return runs.values().stream().map(Session::snapshot).toList();}
 public synchronized boolean cancel(String id){Session s=get(id);if(s.finished)return false;s.cancellationRequested=true;s.events.event(null,null,"CANCELLATION_REQUESTED","Cancellation requested",Map.of(),null);if(s.phase.compareAndSet(0,2)){s.finished=true;s.events.closeReports();s.events.event(null,null,"RUN_CANCELLED","Cancelled before starting",Map.of(),0L);Thread.ofVirtual().start(s.dispatcher::close);}if(s.future!=null)s.future.cancel(true);return true;}
 private static long elapsed(long start){return TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start);}
 @Override public void close(){List<Session> copy;synchronized(this){copy=List.copyOf(runs.values());}copy.stream().filter(s->!s.finished).forEach(s->cancel(s.id));executor.shutdownNow();List<Thread> drains=copy.stream().map(s->Thread.ofVirtual().start(s.dispatcher::close)).toList();long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(2);for(Thread thread:drains)try{thread.join(Math.max(1,(deadline-System.nanoTime())/1_000_000));}catch(InterruptedException e){Thread.currentThread().interrupt();break;}}
 public final class Session{
  public final String id,mode;public final WorkflowStateStore state;public final EventDispatcher dispatcher;public final RunEvents events;private final java.util.concurrent.atomic.AtomicInteger phase=new java.util.concurrent.atomic.AtomicInteger();private volatile boolean finished,cancellationRequested;private Future<?> future;private volatile Map<String,Object> output=Map.of();
  Session(String id,String mode,WorkflowStateStore state,EventDispatcher dispatcher){this.id=id;this.mode=mode;this.state=state;this.dispatcher=dispatcher;this.events=new RunEvents(id,descriptors.get(mode).id(),descriptors.get(mode).version(),dispatcher,state::accept);}
  /** Actual query output is fetched explicitly; never included in events or snapshots. */
  public Map<String,Object> result(){Object status=state.snapshot().get("status");Map<String,Object> result=new LinkedHashMap<>();result.put("runId",id);result.put("mode",mode);result.put("status",status);result.put("available",false);if("SUCCEEDED".equals(status))result.putAll(output);return Collections.unmodifiableMap(result);}
  private EventView view(){return new EventView(views.getOrDefault(mode,List.of()),!views.containsKey(mode));}
  public List<Map<String,Object>> replay(long after){return state.after(after).stream().map(e->view().event(e.toMap())).toList();}
  public Map<String,Object> snapshot(){Map<String,Object> result=new LinkedHashMap<>(state.snapshot());result.put("health",dispatcher.health());result.put("template",template);result.putAll(events.diagnostics());return view().snapshot(result,state.after(0).stream().map(ExecutionEvent::toMap).toList());}
 }
}

